mapper.insert:
/* com.heeji.picket.mapper.ShowReviewsMapper.insert */
INSERT INTO SHOW_REVIEWS (
    SHOW_ID,
    CONTENT,
    INSERT_DATE,
    INSERT_ID
) VALUES (
    #{showId},
    #{content},
    NOW(),
    #{userId}
)

mapper.delete:
/* com.heeji.picket.mapper.ShowReviewsMapper.delete */
DELETE FROM SHOW_REVIEWS
WHERE       1 = 1
AND         REVIEW_ID = #{reviewId}
AND         INSERT_ID = #{userId}
